public static void addContent(MobToteId _toteId, InventQty _qty, refrecid _refRecID, InventDimId _inventDimId)
{
    MobToteContent content;
    ttsbegin;
    select forupdate content where content.ToteId == _toteId && content.RefRecId == _refRecID && content.OrgInventDimId == _inventDimId;
    content.ToteId = _toteId;
    content.Qty += _qty;
    content.RefRecId = _refRecID;
    content.OrgInventDimId = _inventDimId;
    content.write();
    ttscommit;
}

/// <summary>
/// Updates the qty by moving the ToteContent from old line to the new line. The existing line will be deleted or updated and the new will be added.
/// </summary>
/// <param name = "_toteId"></param>
/// <param name = "_qty"></param>
/// <param name = "_refRecIDFrom"></param>
/// <param name = "_refRecIDTo"></param>
public static void updateContent(MobToteId _toteId, InventQty _qty, refrecid _refRecIDFrom, refrecid _refRecIDTo)
{
    MobToteContent content;
    ttsbegin;
    select forupdate content where content.ToteId == _toteId && content.RefRecId == _refRecIDFrom;
    content.ToteId = _toteId;
    content.RefRecId = _refRecIDFrom;
    if (content.RecId)
    {
        if(content.Qty == _qty) // All content is moved so old tote line is deleted
        {
            content.delete();
        }
        else // Otherwise adjust the amount on the original tote line
        {
            content.Qty -= _qty;
            content.update();
        }
    }

    // Move to the new MobToteContent
    content.ToteId = _toteId;
    content.Qty = _qty;
    content.RefRecId = _refRecIDTo;
    content.insert();

    ttscommit;
}

public boolean updateWeight()
{
    boolean				ret;
    ItemId				idTo;
    InventTable			iTbl;
    WMSOrderTrans		orderTrans;
    MobToteTable		toteTable;
    MobDocPackingItems	parmDoc = new MobDocPackingItems();
    boolean				useGrossWeight = parmDoc.parmUseGrossWeight();

    if (this.Qty != this.orig().Qty || !this.orig().Qty)
    {
        select firstonly RouteId, itemId, RecId from orderTrans where orderTrans.RecId == this.RefRecId;
        idTo = orderTrans.itemId;
        iTbl = InventTable::find(idTo);
        ttsbegin;
        toteTable = MobToteTable::FindOrCreate(this.ToteId,null,true);
        iTbl.NetWeight = useGrossWeight ? iTbl.grossWeight() : iTbl.NetWeight;
        toteTable.Weight += (iTbl.netWeight*this.Qty - iTbl.NetWeight*this.orig().Qty);
        toteTable.RefId = orderTrans.RouteId;
        toteTable.update();
        ttscommit;
    }

    return ret;
}
